function cellPosition(i){return i<=5?[6,6-i]:i<=10?[11-i,1]:i<=15?[1,i-9]:[i-14,6];}
function tileDescription(g,i){const c=g.board[i],owner=c.owner===null?'Свободно':g.players[c.owner].name;return `${i+1}. ${c.title}. ${c.kind==='property'?`${owner}. Цена ${c.price}, аренда ${c.currentRent||c.rent}.`:c.kind==='tax'?`Налог ${c.amount}.`:c.kind==='bonus'?`Бонус ${c.amount}.`:''}${g.players.filter(p=>p.alive&&p.pos===i).map(p=>' Здесь '+p.name+'.').join('')}`;}
