function diceMarkup(dice,animate=false){const positions={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};return `<div class="mn-dice ${animate?'confirmed-roll':''}" role="img" aria-label="Кубики: ${dice.join(' и ')}. Всего ${dice[0]+dice[1]}">${dice.map(n=>`<span class="mn-die">${Array.from({length:9},(_,i)=>`<i class="pip ${positions[n].includes(i)?'on':''}"></i>`).join('')}</span>`).join('')}</div>`;}
function cityMarkup(){return `<svg class="mn-city" viewBox="0 0 260 110" fill="none" aria-hidden="true"><path d="M16 102h228M24 102V64h34v38M30 64V46h22v18M35 46V35h12v11M66 102V29h38v73M73 29V16h24v13M111 102V52h35v50M153 102V21h33v81M159 21V9h21v12M194 102V61h39v41M201 61V45h24v16" stroke="currentColor" stroke-width="2"/><path d="M32 75h7m5 0h7M32 85h7m5 0h7M75 41h6m8 0h6M75 53h6m8 0h6M75 65h6m8 0h6M75 77h6m8 0h6M118 64h7m8 0h7M118 77h7m8 0h7M160 34h6m7 0h6M160 46h6m7 0h6M160 58h6m7 0h6M160 70h6m7 0h6M201 73h8m7 0h8M201 85h8m7 0h8" stroke="currentColor" stroke-width="3"/><path d="M45 102V94h6v8M82 102V88h8v14M124 102V89h8v13M166 102V85h8v17M210 102V94h8v8" fill="currentColor"/></svg>`;}
